# ============================================================================
# CONFIG
# ============================================================================

APP_NAME = "CERT.OS"


def _read_version() -> str:
    try:
        script_dir = Path(__file__).resolve().parent
    except NameError:
        script_dir = Path.cwd()
    for candidate in (script_dir / "VERSION", script_dir.parent / "VERSION"):
        try:
            v = candidate.read_text(encoding="utf-8").strip()
            if v:
                return v
        except OSError:
            continue
    return "1.0.0"


APP_VERSION = _read_version()

# Portable data directory: if a 'cert_os_data' folder exists next to the
# script (flash-drive use case), settings/state travel with the device.
# Otherwise fall back to the user's home directory.
def _resolve_data_dir() -> Path:
    try:
        script_dir = Path(__file__).resolve().parent
    except NameError:
        script_dir = Path.cwd()
    portable = script_dir / "cert_os_data"
    if portable.exists() or (script_dir / ".portable").exists():
        portable.mkdir(exist_ok=True)
        return portable
    home = Path.home() / ".cert_os"
    home.mkdir(exist_ok=True)
    return home

DATA_DIR = _resolve_data_dir()
ATTEMPTS_FILE = DATA_DIR / "attempts.json"


