def _expand_bank() -> dict:
    """Convert tuple form to dict form expected by the rest of the app."""
    out = {}
    for cert_id, tuples in _BANK_TUPLES.items():
        out[cert_id] = [
            {"question": t[0], "options": list(t[1]), "correct_index": t[2],
             "topic": t[3], "explanation": t[4]}
            for t in tuples
        ]
    return out


QUESTION_BANK = _expand_bank()


def get_bank_count(cert_id: str) -> int:
    return len(QUESTION_BANK.get(cert_id, []))


def total_bank_count() -> int:
    return sum(len(qs) for qs in QUESTION_BANK.values())


def pick_from_bank(cert_id: str, n: int) -> list:
    """Return n random questions from the bank for a cert. If bank smaller
    than n, returns all available in random order (caller should handle)."""
    pool = QUESTION_BANK.get(cert_id, [])
    if not pool:
        return []
    if len(pool) <= n:
        out = list(pool)
        random.shuffle(out)
        return out
    return random.sample(pool, n)


# ============================================================================
# STATE
# ============================================================================

@dataclass
class ExamAttempt:
    ts: float
    cert_id: str
    total: int
    correct: int
    duration_seconds: int = 0

    @property
    def percentage(self) -> float:
        return (self.correct / self.total * 100) if self.total else 0.0

    @property
    def date_str(self) -> str:
        return datetime.fromtimestamp(self.ts).strftime("%Y-%m-%d %H:%M")


def load_attempts() -> list[ExamAttempt]:
    if not ATTEMPTS_FILE.exists():
        return []
    try:
        data = json.loads(ATTEMPTS_FILE.read_text())
        return [ExamAttempt(**d) for d in data]
    except Exception:
        return []


def save_attempt(attempt: ExamAttempt) -> None:
    attempts = load_attempts()
    attempts.append(attempt)
    attempts = attempts[-100:]
    try:
        ATTEMPTS_FILE.write_text(
            json.dumps([asdict(a) for a in attempts], indent=2)
        )
    except Exception:
        pass


def last_attempt_for(cert_id: str) -> Optional[ExamAttempt]:
    for a in reversed(load_attempts()):
        if a.cert_id == cert_id:
            return a
    return None


# ============================================================================
# EXAM GENERATION (from built-in bank)
# ============================================================================

class ExamGenerator(QThread):
    """Builds a full exam by drawing from the built-in question bank."""
    progress = Signal(int, int)   # current_count, total
    status = Signal(str)
    finished_ok = Signal(list)    # list of question dicts
    finished_err = Signal(str)

    def __init__(self, cert_id: str, total: int):
        super().__init__()
        self.cert_id = cert_id
        self.total = total
        self._stop = False

    def stop(self):
        self._stop = True

    def run(self):
        self.status.emit("loading from built-in question bank...")
        self.progress.emit(0, self.total)
        questions = pick_from_bank(self.cert_id, self.total)
        if not questions:
            self.finished_err.emit(
                f"no questions in the built-in bank for this certification.\n\n"
                f"add questions to _BANK_TUPLES['{self.cert_id}'] in cert_os.py."
            )
            return
        # If bank is smaller than requested, repeat with reshuffle to fill
        while len(questions) < self.total:
            more = pick_from_bank(self.cert_id, self.total - len(questions))
            if not more:
                break
            questions.extend(more)
        questions = questions[:self.total]
        random.shuffle(questions)
        self.progress.emit(len(questions), self.total)
        self.finished_ok.emit(questions)


