class ScanlineOverlay(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.setAttribute(Qt.WA_TranslucentBackground, True)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setPen(Qt.NoPen)
        p.setBrush(QColor(0, 0, 0, 50))
        h = self.height()
        w = self.width()
        for y in range(0, h, 3):
            p.drawRect(0, y, w, 1)
        grad = QLinearGradient(0, 0, 0, h)
        grad.setColorAt(0, QColor(0, 0, 0, 90))
        grad.setColorAt(0.4, QColor(0, 0, 0, 0))
        grad.setColorAt(0.6, QColor(0, 0, 0, 0))
        grad.setColorAt(1, QColor(0, 0, 0, 90))
        p.setBrush(QBrush(grad))
        p.drawRect(0, 0, w, h)


def hr() -> QFrame:
    f = QFrame()
    f.setFrameShape(QFrame.HLine)
    f.setStyleSheet("color: #1a4a1a; background-color: #1a4a1a; border: none; max-height: 1px;")
    return f


# ============================================================================
# CORNER-BRACKET PANEL - Aliens-style chunky UI frame
# ============================================================================

class BracketPanel(QFrame):
    """A QFrame with painted corner brackets like Nostromo MOTHER terminal."""
    def __init__(self, parent=None, color: str = "#66ff66"):
        super().__init__(parent)
        self.setObjectName("panel")
        self._bracket_color = QColor(color)
        self._bracket_size = 14
        self._bracket_pen = 2

    def paintEvent(self, event):
        super().paintEvent(event)
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, False)
        pen = p.pen()
        pen.setColor(self._bracket_color)
        pen.setWidth(self._bracket_pen)
        p.setPen(pen)
        s = self._bracket_size
        w, h = self.width(), self.height()
        off = 4
        # top-left
        p.drawLine(off, off, off + s, off)
        p.drawLine(off, off, off, off + s)
        # top-right
        p.drawLine(w - off - s, off, w - off, off)
        p.drawLine(w - off, off, w - off, off + s)
        # bottom-left
        p.drawLine(off, h - off - s, off, h - off)
        p.drawLine(off, h - off, off + s, h - off)
        # bottom-right
        p.drawLine(w - off, h - off - s, w - off, h - off)
        p.drawLine(w - off - s, h - off, w - off, h - off)


