class CertCard(QFrame):
    clicked = Signal(str)

    def __init__(self, cert_id: str, cert: dict, last: Optional[ExamAttempt], parent=None):
        super().__init__(parent)
        self.cert_id = cert_id
        self.setObjectName("certCard")
        self.setStyleSheet(
            f"QFrame#certCard {{ border-left: 3px solid {cert['color']}; }}"
            f"QFrame#certCard:hover {{ background-color: #122d12; "
            f"border-color: {cert['color']}; }}"
        )
        self.setCursor(Qt.PointingHandCursor)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(14, 12, 14, 12)
        layout.setSpacing(6)

        code = QLabel(cert["code"])
        code.setStyleSheet("color: #2a6a2a; font-size: 10px; letter-spacing: 2px;")
        layout.addWidget(code)

        name = QLabel(cert["name"])
        name.setStyleSheet(
            f"color: {cert['color']}; font-size: 18px; font-weight: 700; letter-spacing: 1px;"
        )
        name.setWordWrap(True)
        layout.addWidget(name)

        blurb = QLabel(cert["blurb"])
        blurb.setStyleSheet("color: #9ec99e; font-size: 11px;")
        blurb.setWordWrap(True)
        blurb.setMinimumHeight(34)
        layout.addWidget(blurb)

        layout.addWidget(hr())

        meta_row = QHBoxLayout()
        meta_row.setSpacing(10)
        passing = QLabel(
            f"<span style='color:#2a6a2a'>PASS </span>"
            f"<span style='color:#00ff85; font-weight:700'>{cert['pass_score']}%</span>"
        )
        passing.setStyleSheet("font-size: 11px; letter-spacing: 1px;")
        meta_row.addWidget(passing)

        if last:
            color = "#00ff85" if last.percentage >= cert["pass_score"] else "#ff3060"
            verdict = "PASS" if last.percentage >= cert["pass_score"] else "FAIL"
            meta_row.addWidget(QLabel("<span style='color:#2a6a2a'>|</span>"))
            last_lbl = QLabel(
                f"<span style='color:#2a6a2a'>LAST </span>"
                f"<span style='color:{color}; font-weight:700'>{last.percentage:.0f}% {verdict}</span>"
            )
            last_lbl.setStyleSheet("font-size: 11px; letter-spacing: 1px;")
            meta_row.addWidget(last_lbl)
        meta_row.addStretch()
        layout.addLayout(meta_row)

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.clicked.emit(self.cert_id)
        super().mousePressEvent(event)


