class BootScreen(QWidget):
    """Plays a boot sequence on app launch before transitioning to the menu."""
    finished = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.boot_done = False

        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(0)

        # Big header block
        hdr = QLabel(self._header_text())
        hdr.setStyleSheet(
            "color: #66ff66; font-family: 'Cascadia Mono', monospace; "
            "font-size: 13px; line-height: 1.0; letter-spacing: 1px; font-weight: 700;"
        )
        hdr.setAlignment(Qt.AlignCenter)
        layout.addWidget(hdr)

        layout.addSpacing(10)

        bar = QLabel("═" * 72)
        bar.setStyleSheet("color: #1a4a1a; font-size: 12px;")
        bar.setAlignment(Qt.AlignCenter)
        layout.addWidget(bar)

        layout.addSpacing(8)

        # Scrolling boot log
        self.log_lbl = QLabel("")
        self.log_lbl.setStyleSheet(
            "color: #66ff66; font-family: 'Cascadia Mono', monospace; "
            "font-size: 13px; line-height: 1.65; letter-spacing: 1px;"
        )
        self.log_lbl.setAlignment(Qt.AlignTop | Qt.AlignLeft)
        self.log_lbl.setTextFormat(Qt.RichText)
        self.log_lbl.setWordWrap(False)
        layout.addWidget(self.log_lbl)

        layout.addStretch()

        # Footer with continue prompt
        self.footer_lbl = QLabel("")
        self.footer_lbl.setStyleSheet(
            "color: #ffb000; font-family: 'Cascadia Mono', monospace; "
            "font-size: 14px; letter-spacing: 3px; font-weight: 700;"
        )
        self.footer_lbl.setAlignment(Qt.AlignCenter)
        layout.addWidget(self.footer_lbl)

        bar2 = QLabel("═" * 72)
        bar2.setStyleSheet("color: #1a4a1a; font-size: 12px;")
        bar2.setAlignment(Qt.AlignCenter)
        layout.addWidget(bar2)

        # focus to receive keypress
        self.setFocusPolicy(Qt.StrongFocus)

        self.lines: list[str] = []
        self.queue: list = []  # list of (text, delay_ms) or callables
        self._build_queue()
        QTimer.singleShot(300, self._tick)

    @staticmethod
    def _header_text() -> str:
        return (
            "  ┌────────────────────────────────────────────────────────────────────┐\n"
            "  │   M.U.T.H.U.R 6000  ::  CERTIFICATION TRAINING SUBSYSTEM           │\n"
            "  │   WEYLAND-YUTANI INTERFACE  ::  PRIORITY ALPHA  ::  REGISTRY 6011  │\n"
            "  └────────────────────────────────────────────────────────────────────┘"
        )

    def _q(self, line: str, delay: int = 90):
        self.queue.append((line, delay))

    def _build_queue(self):
        self._q("<span style='color:#2a6a2a'>[BIOS]</span> CERT.OS bootloader v" + APP_VERSION + " ......... <span style='color:#66ff66'>OK</span>", 80)
        self._q("<span style='color:#2a6a2a'>[INIT]</span> POST self-test ............................ <span style='color:#66ff66'>PASS</span>", 80)
        self._q("<span style='color:#2a6a2a'>[INIT]</span> mounting /knowledge ....................... <span style='color:#66ff66'>OK</span>", 70)
        self._q("<span style='color:#2a6a2a'>[INIT]</span> loading certification modules ............. <span style='color:#66ff66'>OK</span>", 70)
        for cert_id, cert in CERTS.items():
            qcount = get_bank_count(cert_id)
            qstr = f"<span style='color:#aaffaa'>{qcount:>3} Q</span>" if qcount > 0 else "<span style='color:#ffb000'>  0 Q</span>"
            self._q(
                f"       <span style='color:#2a6a2a'>›</span> "
                f"<span style='color:#aaffaa'>{cert['name']:<30}</span> "
                f"<span style='color:#2a6a2a'>{cert['code']:<14}</span> "
                f"{qstr} "
                f"<span style='color:#66ff66'>LOADED</span>",
                25,
            )
        self._q("", 30)
        self._q(
            f"<span style='color:#2a6a2a'>[BANK]</span> question bank total: "
            f"<span style='color:#66ff66'>{total_bank_count()}</span> "
            f"<span style='color:#2a6a2a'>questions across {len(CERTS)} certifications</span>",
            80,
        )
        self._q("", 60)
        self._q(
            "<span style='color:#2a6a2a'>[ CHK]</span> question integrity ........................ "
            "<span style='color:#66ff66'>OK</span>",
            90,
        )
        self._q(
            "<span style='color:#2a6a2a'>[ CHK]</span> answer keys verified ...................... "
            "<span style='color:#66ff66'>OK</span>",
            90,
        )
        self._q("", 80)
        self._q(
            "<span style='color:#66ff66'>[ ok ]</span> system ready. all subsystems "
            "<span style='color:#66ff66'>NOMINAL</span>.",
            100,
        )
        self.queue.append(("__DONE__", 0))

    def _tick(self):
        if not self.queue:
            return
        item = self.queue.pop(0)
        if isinstance(item, tuple) and item[0] == "__DONE__":
            self.boot_done = True
            self.footer_lbl.setText("» PRESS ANY KEY OR CLICK TO CONTINUE «")
            return
        line, delay = item
        self.lines.append(line)
        # render last 25 lines
        visible = self.lines[-25:]
        self.log_lbl.setText("<br>".join(visible))
        QTimer.singleShot(delay, self._tick)

    def keyPressEvent(self, event):
        if not self.boot_done:
            self.queue.clear()
        self.finished.emit()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.keyPressEvent(None)


