        hist_btn.clicked.connect(self.show_history.emit)
        head.addWidget(hist_btn)
        layout.addLayout(head)

        sub = QLabel(
            "pick a certification. cert.os will generate a full practice exam "
            "and tell you whether you'd pass."
        )
        sub.setStyleSheet("color: #2a6a2a; font-size: 11px; letter-spacing: 1px;")
        sub.setWordWrap(True)
        layout.addWidget(sub)

        grid = QGridLayout()
