        left.addLayout(top_row)

        # progress bar
        self.bar = QProgressBar()
        self.bar.setMaximum(100)
        self.bar.setTextVisible(False)
        left.addWidget(self.bar)

        # question card
        card = QFrame()
        card.setObjectName("panel")
        card_layout = QVBoxLayout(card)
        card_layout.setContentsMargins(20, 18, 20, 18)
        card_layout.setSpacing(14)

        topic_row = QHBoxLayout()
        self.topic_lbl = QLabel("")
        self.topic_lbl.setStyleSheet("color: #00e0ff; font-size: 11px; letter-spacing: 2px;")
        topic_row.addWidget(self.topic_lbl)
        topic_row.addStretch()
        self.flag_btn = QPushButton("⚑ FLAG")
        self.flag_btn.setMaximumHeight(28)
        self.flag_btn.clicked.connect(self._toggle_flag)
        topic_row.addWidget(self.flag_btn)
        card_layout.addLayout(topic_row)

        self.q_lbl = QLabel("")
        self.q_lbl.setStyleSheet(
            "color: #ffd56b; font-size: 15px; line-height: 1.55;"
        )
        self.q_lbl.setWordWrap(True)
        self.q_lbl.setTextFormat(Qt.PlainText)
        card_layout.addWidget(self.q_lbl)

        self.options_box = QVBoxLayout()
