class ResultsScreen(QWidget):
    review_wrong = Signal()
    home = Signal()
    again = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.results: dict = {}
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(14)

        # verdict banner
        self.verdict = QLabel("")
        self.verdict.setAlignment(Qt.AlignCenter)
        self.verdict.setStyleSheet(
            "font-size: 64px; font-weight: 700; letter-spacing: 8px;"
        )
        layout.addWidget(self.verdict)

        self.subline = QLabel("")
        self.subline.setAlignment(Qt.AlignCenter)
        self.subline.setStyleSheet("color: #2a6a2a; font-size: 13px; letter-spacing: 2px;")
        layout.addWidget(self.subline)

        # main score panel
        score_panel = QFrame()
        score_panel.setObjectName("panel")
        sp = QHBoxLayout(score_panel)
        sp.setContentsMargins(20, 20, 20, 20)
        sp.setSpacing(40)

        self.stat_widgets = {}
        for key, label, color in [
            ("score", "YOUR SCORE", "#ffb000"),
            ("required", "PASSING", "#00ff85"),
            ("correct", "CORRECT", "#00e0ff"),
            ("wrong", "WRONG", "#ff3060"),
            ("time", "TIME", "#9ec99e"),
        ]:
            box = QVBoxLayout()
            box.setSpacing(2)
            v = QLabel("--")
            v.setAlignment(Qt.AlignCenter)
            v.setStyleSheet(
                f"color: {color}; font-size: 32px; font-weight: 700; letter-spacing: 1px;"
            )
            l = QLabel(label)
            l.setAlignment(Qt.AlignCenter)
            l.setStyleSheet("color: #2a6a2a; font-size: 10px; letter-spacing: 2px;")
            box.addWidget(v)
            box.addWidget(l)
            wrap = QWidget()
            wrap.setLayout(box)
            sp.addWidget(wrap)
            self.stat_widgets[key] = v
        layout.addWidget(score_panel)

        # delta vs passing
        self.delta_lbl = QLabel("")
        self.delta_lbl.setAlignment(Qt.AlignCenter)
        self.delta_lbl.setStyleSheet("font-size: 12px; letter-spacing: 2px;")
        layout.addWidget(self.delta_lbl)

        # per-topic breakdown
        topics_panel = QFrame()
        topics_panel.setObjectName("panel")
        tpv = QVBoxLayout(topics_panel)
        tpv.setContentsMargins(16, 14, 16, 14)
        tpv.setSpacing(10)
        topics_title = QLabel("PERFORMANCE BY TOPIC")
        topics_title.setStyleSheet(
            "color: #66ff66; font-size: 12px; font-weight: 700; letter-spacing: 2px;"
        )
        tpv.addWidget(topics_title)

        self.topics_scroll = QScrollArea()
        self.topics_scroll.setWidgetResizable(True)
        self.topics_scroll.setStyleSheet("border: none;")
        self.topics_inner = QWidget()
        self.topics_layout = QVBoxLayout(self.topics_inner)
        self.topics_layout.setContentsMargins(0, 0, 0, 0)
        self.topics_layout.setSpacing(4)
        self.topics_scroll.setWidget(self.topics_inner)
        self.topics_scroll.setMinimumHeight(160)
        self.topics_scroll.setMaximumHeight(220)
        tpv.addWidget(self.topics_scroll)

        layout.addWidget(topics_panel)

        # buttons
        bot = QHBoxLayout()
        bot.addStretch()
        self.review_btn = QPushButton("REVIEW WRONG ANSWERS")
        self.review_btn.clicked.connect(self.review_wrong.emit)
        bot.addWidget(self.review_btn)
        again_btn = QPushButton("RUN AGAIN")
        again_btn.clicked.connect(self.again.emit)
        bot.addWidget(again_btn)
        home_btn = QPushButton("HOME >")
        home_btn.setObjectName("primaryBtn")
        home_btn.setMinimumWidth(140)
        home_btn.clicked.connect(self.home.emit)
        bot.addWidget(home_btn)
        bot.addStretch()
        layout.addLayout(bot)

    def show_results(self, results: dict):
        self.results = results
        cert = CERTS[results["cert_id"]]
        total = results["total"]
        correct = results["correct"]
        wrong = total - correct
        pct = correct / total * 100 if total else 0
        passing = cert["pass_score"]
        passed = pct >= passing

        if passed:
            self.verdict.setText("PASS")
            self.verdict.setStyleSheet(
                "color: #00ff85; font-size: 80px; font-weight: 700; letter-spacing: 12px;"
            )
            self.subline.setText(
                f"you'd pass the {cert['name']} exam at this level."
            )
        else:
            self.verdict.setText("FAIL")
            self.verdict.setStyleSheet(
                "color: #ff3060; font-size: 80px; font-weight: 700; letter-spacing: 12px;"
            )
            self.subline.setText(
                f"below cutoff. review the wrong answers and try again."
            )

        self.stat_widgets["score"].setText(f"{pct:.0f}%")
        self.stat_widgets["required"].setText(f"{passing}%")
        self.stat_widgets["correct"].setText(str(correct))
        self.stat_widgets["wrong"].setText(str(wrong))
        m = results["duration"] // 60
        s = results["duration"] % 60
        self.stat_widgets["time"].setText(f"{m}:{s:02d}")

        delta = pct - passing
        if passed:
            self.delta_lbl.setText(
                f"<span style='color:#00ff85'>+{delta:.1f} points above passing</span>"
            )
        else:
            self.delta_lbl.setText(
                f"<span style='color:#ff3060'>{delta:.1f} points below passing</span>"
            )

        # topic breakdown
        while self.topics_layout.count():
            item = self.topics_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        topics = sorted(
            results["per_topic_total"].items(),
            key=lambda kv: (
                results["per_topic_correct"].get(kv[0], 0) / kv[1] if kv[1] else 0
            ),
        )
        for topic, ttotal in topics:
            tcorrect = results["per_topic_correct"].get(topic, 0)
            tpct = tcorrect / ttotal * 100 if ttotal else 0
            color = "#00ff85" if tpct >= passing else ("#ffb000" if tpct >= 60 else "#ff3060")
            row = QHBoxLayout()
            name = QLabel(topic)
            name.setStyleSheet("color: #c8e8c8; font-size: 12px;")
            name.setWordWrap(True)
            row.addWidget(name, stretch=2)
            stat = QLabel(
                f"<span style='color:{color}; font-weight:700'>{tcorrect}/{ttotal}</span>"
                f"<span style='color:#2a6a2a'>  {tpct:.0f}%</span>"
            )
            stat.setStyleSheet("font-size: 12px; letter-spacing: 1px;")
            row.addWidget(stat)
            row_w = QWidget()
            row_w.setLayout(row)
            self.topics_layout.addWidget(row_w)
        self.topics_layout.addStretch()

        self.review_btn.setVisible(wrong > 0)


