class ReviewScreen(QWidget):
    back = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(12)

        head = QHBoxLayout()
        back_btn = QPushButton("< BACK TO RESULTS")
        back_btn.clicked.connect(self.back.emit)
        head.addWidget(back_btn)
        head.addStretch()
        layout.addLayout(head)

        title = QLabel("WRONG ANSWERS")
        title.setStyleSheet(
            "color: #ff2e88; font-size: 22px; font-weight: 700; letter-spacing: 3px;"
        )
        layout.addWidget(title)

        self.summary = QLabel("")
        self.summary.setStyleSheet("color: #2a6a2a; font-size: 11px; letter-spacing: 1px;")
        layout.addWidget(self.summary)
        layout.addWidget(hr())

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet("border: none;")
        self.inner = QWidget()
        self.inner_layout = QVBoxLayout(self.inner)
        self.inner_layout.setContentsMargins(0, 0, 0, 0)
        self.inner_layout.setSpacing(10)
        scroll.setWidget(self.inner)
        layout.addWidget(scroll)

    def show_wrong(self, wrong_entries: list[dict]):
        while self.inner_layout.count():
            item = self.inner_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        self.summary.setText(f"{len(wrong_entries)} question(s) missed")

        for n, entry in enumerate(wrong_entries, 1):
            card = QFrame()
            card.setObjectName("panel")
            cl = QVBoxLayout(card)
            cl.setContentsMargins(14, 12, 14, 12)
            cl.setSpacing(6)

            head = QLabel(
                f"<span style='color:#ff2e88; font-weight:700'>#{n}</span>"
                f"  <span style='color:#2a6a2a'>// {entry.get('topic','?')}</span>"
            )
            head.setStyleSheet("font-size: 11px; letter-spacing: 1px;")
            cl.addWidget(head)

            q = QLabel(entry["question"])
            q.setStyleSheet("color: #ffd56b; font-size: 13px;")
            q.setWordWrap(True)
            cl.addWidget(q)

            ci = entry["correct_index"]
            pi = entry["picked_index"]
            for i, opt in enumerate(entry["options"]):
                pre = f"  [{chr(65+i)}]"
                if i == ci:
                    color = "#00ff85"
                    suf = "  <- correct answer"
                elif i == pi:
                    color = "#ff3060"
                    suf = "  <- you picked"
                elif pi == -1 and i == 0:
                    color = "#666"
                    suf = ""
                else:
                    color = "#666"
                    suf = ""
                ol = QLabel(f"<span style='color:{color}'>{pre} {opt}{suf}</span>")
                ol.setStyleSheet("font-size: 12px;")
                ol.setWordWrap(True)
                cl.addWidget(ol)

            if pi == -1:
                no_ans = QLabel("<span style='color:#ff3060; font-style:italic'>(unanswered)</span>")
                no_ans.setStyleSheet("font-size: 11px;")
                cl.addWidget(no_ans)

            ex = QLabel(entry.get("explanation", ""))
            ex.setStyleSheet(
                "color: #9ec99e; font-size: 11px; padding: 8px; "
                "background: #061206; border: 1px solid #1a4a1a; margin-top: 6px;"
            )
            ex.setWordWrap(True)
            cl.addWidget(ex)

            self.inner_layout.addWidget(card)
        self.inner_layout.addStretch()


# ============================================================================
# UI: HISTORY SCREEN
# ============================================================================

class HistoryScreen(QWidget):
    back = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(12)

        head = QHBoxLayout()
        back_btn = QPushButton("< BACK")
        back_btn.clicked.connect(self.back.emit)
        head.addWidget(back_btn)
        head.addStretch()
        layout.addLayout(head)

        title = QLabel("EXAM HISTORY")
        title.setStyleSheet(
            "color: #66ff66; font-size: 22px; font-weight: 700; letter-spacing: 3px;"
        )
        layout.addWidget(title)
        layout.addWidget(hr())

        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setStyleSheet("border: none;")
        self.inner = QWidget()
        self.inner_layout = QVBoxLayout(self.inner)
        self.inner_layout.setContentsMargins(0, 0, 0, 0)
        self.inner_layout.setSpacing(8)
        self.scroll.setWidget(self.inner)
        layout.addWidget(self.scroll)

    def refresh(self):
        while self.inner_layout.count():
            item = self.inner_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        attempts = list(reversed(load_attempts()))
        if not attempts:
            l = QLabel("no exam attempts yet.")
            l.setStyleSheet("color: #555; font-size: 12px; padding: 40px;")
            l.setAlignment(Qt.AlignCenter)
            self.inner_layout.addWidget(l)
            self.inner_layout.addStretch()
            return

        for a in attempts:
            cert = CERTS.get(a.cert_id, {"name": a.cert_id, "color": "#888", "pass_score": 0})
            passed = a.percentage >= cert["pass_score"]
            color = "#00ff85" if passed else "#ff3060"
            verdict = "PASS" if passed else "FAIL"

            card = QFrame()
            card.setObjectName("panel")
            cl = QHBoxLayout(card)
            cl.setContentsMargins(14, 10, 14, 10)
            cl.setSpacing(14)

            left = QVBoxLayout()
            left.setSpacing(2)
            cert_lbl = QLabel(
                f"<span style='color:{cert['color']}; font-weight:700'>{cert['name']}</span>"
            )
            cert_lbl.setStyleSheet("font-size: 13px; letter-spacing: 1px;")
            left.addWidget(cert_lbl)
            date_lbl = QLabel(a.date_str)
            date_lbl.setStyleSheet("color: #2a6a2a; font-size: 11px; letter-spacing: 1px;")
            left.addWidget(date_lbl)
            wrap = QWidget()
            wrap.setLayout(left)
            cl.addWidget(wrap, stretch=1)

            stats = QLabel(
                f"<span style='color:#2a6a2a'>{a.correct}/{a.total}</span>  "
                f"<span style='color:{color}; font-weight:700; font-size: 16px;'>{a.percentage:.0f}%</span>  "
                f"<span style='color:{color}; font-weight:700'>{verdict}</span>"
            )
            stats.setStyleSheet("font-size: 12px; letter-spacing: 1px;")
            cl.addWidget(stats)

            self.inner_layout.addWidget(card)
        self.inner_layout.addStretch()


# ============================================================================
# MAIN WINDOW
# ============================================================================

class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"{APP_NAME} v{APP_VERSION}")
        self.resize(1280, 860)
        self.setMinimumSize(1080, 720)

        self.generator: Optional[ExamGenerator] = None
        self._last_results: Optional[dict] = None
        self._last_cert_id: Optional[str] = None
        self._last_total: Optional[int] = None

        central = QWidget()
        outer = QVBoxLayout(central)
        outer.setContentsMargins(14, 14, 14, 14)
        outer.setSpacing(10)

        self.topbar = TopBar()
        outer.addWidget(self.topbar)

        self.stack = QStackedWidget()
        outer.addWidget(self.stack, stretch=1)

        self.boot = BootScreen()
        self.boot.finished.connect(self._boot_finished)

        self.menu = MenuScreen()
        self.config = ConfigScreen()
        self.loading = LoadingScreen()
        self.exam = ExamScreen()
        self.results = ResultsScreen()
        self.review = ReviewScreen()
        self.history = HistoryScreen()

        for s in (self.boot, self.menu, self.config, self.loading, self.exam,
                  self.results, self.review, self.history):
            self.stack.addWidget(s)

        # wiring
        self.menu.cert_chosen.connect(self._cert_chosen)
        self.menu.show_history.connect(self._open_history)
        self.config.back.connect(lambda: self._open_menu())
        self.config.start.connect(self._begin_generation)
        self.loading.cancelled.connect(self._cancel_gen)
        self.exam.submitted.connect(self._on_submitted)
        self.exam.aborted.connect(lambda: self._open_menu())
        self.results.review_wrong.connect(self._open_review)
        self.results.again.connect(self._again)
        self.results.home.connect(lambda: self._open_menu())
        self.review.back.connect(lambda: self._goto(self.results))
        self.history.back.connect(lambda: self._open_menu())

        self.setCentralWidget(central)

        self.overlay = ScanlineOverlay(self)
        self.overlay.raise_()
        self.overlay.setGeometry(self.rect())

        # start at boot
        self.stack.setCurrentWidget(self.boot)
        self.topbar.set_status("BOOTING")

        # answer hotkeys A/B/C/D
        for letter, idx in [("A", 0), ("B", 1), ("C", 2), ("D", 3)]:
            QShortcut(QKeySequence(letter), self, activated=lambda i=idx: self._hotkey_answer(i))
        QShortcut(QKeySequence("Right"), self, activated=self._hotkey_next)
        QShortcut(QKeySequence("Left"), self, activated=self._hotkey_prev)
        QShortcut(QKeySequence("F"), self, activated=self._hotkey_flag)

    def _boot_finished(self):
        self._open_menu()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, "overlay"):
            self.overlay.setGeometry(self.rect())

    def _goto(self, w: QWidget):
        self.stack.setCurrentWidget(w)
        # update top bar status
        names = {
            self.menu: "READY",
            self.config: "CONFIG",
            self.loading: "GENERATING",
            self.exam: "EXAM IN PROGRESS",
            self.results: "RESULTS",
            self.review: "REVIEW",
            self.history: "HISTORY",
        }
        self.topbar.set_status(names.get(w, "READY"))

    def _open_menu(self):
        # rebuild menu so cards reflect latest history
        new_menu = MenuScreen()
        new_menu.cert_chosen.connect(self._cert_chosen)
        new_menu.show_history.connect(self._open_history)
        idx = self.stack.indexOf(self.menu)
        self.stack.insertWidget(idx, new_menu)
        self.stack.removeWidget(self.menu)
        self.menu.deleteLater()
        self.menu = new_menu
        self._goto(self.menu)

    def _open_history(self):
        self.history.refresh()
        self._goto(self.history)

    def _open_review(self):
        wrong = self._last_results.get("wrong", []) if self._last_results else []
        self.review.show_wrong(wrong)
        self._goto(self.review)

    def _cert_chosen(self, cert_id: str):
        self.config.set_cert(cert_id)
        self._goto(self.config)

    def _begin_generation(self, cert_id: str, total: int):
        self._last_cert_id = cert_id
        self._last_total = total
        cert = CERTS[cert_id]
        self.loading.set_cert(cert, total)
        self._goto(self.loading)

        self.generator = ExamGenerator(cert_id, total)
        self.generator.progress.connect(self.loading.update_progress)
        self.generator.status.connect(self.loading.update_status)
        self.generator.finished_ok.connect(self._gen_done)
        self.generator.finished_err.connect(self._gen_err)
        self.generator.start()

    def _cancel_gen(self):
        if self.generator and self.generator.isRunning():
            self.generator.stop()
            self.generator.wait(2000)
        self._open_menu()

    def _gen_done(self, questions: list[dict]):
        self.exam.start_exam(self._last_cert_id, questions)
        self._goto(self.exam)

    def _gen_err(self, msg: str):
        QMessageBox.warning(self, "GENERATION ERROR", msg)
        self._open_menu()

    def _on_submitted(self, results: dict):
        self._last_results = results
        attempt = ExamAttempt(
            ts=time.time(),
            cert_id=results["cert_id"],
            total=results["total"],
            correct=results["correct"],
            duration_seconds=results["duration"],
        )
        save_attempt(attempt)
        self.results.show_results(results)
        self._goto(self.results)

    def _again(self):
        if self._last_cert_id and self._last_total:
            self._begin_generation(self._last_cert_id, self._last_total)

    # hotkey handlers
    def _hotkey_answer(self, idx: int):
        if self.stack.currentWidget() is self.exam and self.exam.option_buttons:
            if 0 <= idx < len(self.exam.option_buttons):
                self.exam._pick(idx)

    def _hotkey_next(self):
        if self.stack.currentWidget() is self.exam:
            self.exam._next()

    def _hotkey_prev(self):
        if self.stack.currentWidget() is self.exam:
            self.exam._prev()

    def _hotkey_flag(self):
        if self.stack.currentWidget() is self.exam:
            self.exam._toggle_flag()


# ============================================================================
# ENTRY
# ============================================================================

def main():
    app = QApplication(sys.argv)
    app.setApplicationName(APP_NAME)
    app.setStyleSheet(QSS)

    pal = app.palette()
    pal.setColor(QPalette.Window, QColor("#040804"))
    pal.setColor(QPalette.WindowText, QColor("#66ff66"))
    pal.setColor(QPalette.Base, QColor("#0a1a0a"))
    pal.setColor(QPalette.Text, QColor("#66ff66"))
    pal.setColor(QPalette.Highlight, QColor("#ffb000"))
    pal.setColor(QPalette.HighlightedText, QColor("#040804"))
    app.setPalette(pal)

    win = MainWindow()
    win.show()
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
